-- For a managed Field of Scale volume with its exact prior ready digest.
-- Run after final Rathe definitions are installed, with writers stopped.
DELIMITER $$
BEGIN NOT ATOMIC
 DECLARE old_digest CHAR(64) DEFAULT NULL;
 DECLARE old_state VARCHAR(16) DEFAULT NULL;
 DECLARE marker_started BOOLEAN DEFAULT FALSE;
 DECLARE EXIT HANDLER FOR SQLEXCEPTION
 BEGIN
  IF marker_started THEN ROLLBACK; END IF;
  RESIGNAL;
 END;
 IF DATABASE() IS NULL OR DATABASE()<>'peq_full' OR @@in_transaction<>0 OR COALESCE(@rathe_20261117_marker_authorized,0)<>1 THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Require reviewed managed Rathe marker transition';
 END IF;
 IF (SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name='everforge_bootstrap' AND engine='InnoDB')<>1 THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Managed bootstrap marker absent';
 END IF;
 START TRANSACTION;
 SET marker_started=TRUE;
 SELECT sql_sha256,state INTO old_digest,old_state FROM everforge_bootstrap WHERE id=1 FOR UPDATE;
 IF NOT(old_digest <=> 'e5bc30356530ca289806697e504586ac7121ff019277814cf9d0028aa0cc9ce9') OR NOT(old_state <=> 'ready') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Unsupported prior seed or marker state'; END IF;
 IF (SELECT COUNT(*) FROM `tasks` WHERE `id` <=> 920216 AND `type` <=> 2 AND `duration` <=> 0 AND `duration_code` <=> 0 AND BINARY `title` <=> BINARY CONVERT(X'526574696e7565206f66207468652046726f672d476f64' USING utf8mb4) AND BINARY `description` <=> BINARY CONVERT(X'4b6f7261736369616e2073656e74696e656c730a53746572696b2047726973746d616b6572' USING utf8mb4) AND BINARY `reward_text` <=> BINARY CONVERT(X'52617468652070726f6772657373696f6e2072657761726473' USING utf8mb4) AND BINARY `reward_id_list` <=> BINARY '' AND `cash_reward` <=> 0 AND `exp_reward` <=> 0 AND `reward_method` <=> 3 AND `reward_points` <=> 0 AND `reward_point_type` <=> 0 AND `min_level` <=> 75 AND `max_level` <=> 100 AND `level_spread` <=> 15 AND `min_players` <=> 1 AND `max_players` <=> 1 AND `repeatable` <=> 1 AND `faction_reward` <=> 0 AND BINARY `completion_emote` <=> BINARY '' AND `replay_timer_group` <=> 0 AND `replay_timer_seconds` <=> 19200 AND `request_timer_group` <=> 0 AND `request_timer_seconds` <=> 0 AND `dz_template_id` <=> 0 AND `lock_activity_id` <=> -1 AND `faction_amount` <=> 0 AND `enabled` <=> 1)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Rathe exact public postimage differs: tasks'; END IF;
